#include <vector>
#include <algorithm>

class Solution {
public:
    long long minCost(int n, std::vector<std::vector<int>>& cost) {
        int half = n / 2;
        const long long INF = 1e18;
        std::vector<std::vector<long long>> dp(3, std::vector<long long>(3, INF));

        for (int c1 = 0; c1 < 3; ++c1) {
            for (int c2 = 0; c2 < 3; ++c2) {
                if (c1 != c2) {
                    dp[c1][c2] = cost[0][c1] + cost[n - 1][c2];
                }
            }
        }

        for (int i = 1; i < half; ++i) {
            std::vector<std::vector<long long>> next_dp(3, std::vector<long long>(3, INF));
            for (int c1 = 0; c1 < 3; ++c1) {
                for (int c2 = 0; c2 < 3; ++c2) {
                    if (c1 == c2) continue;
                    long long c_add = cost[i][c1] + cost[n - 1 - i][c2];
                    long long best_prev = INF;
                    for (int p1 = 0; p1 < 3; ++p1) {
                        if (p1 == c1) continue;
                        for (int p2 = 0; p2 < 3; ++p2) {
                            if (p2 == c2) continue;
                            best_prev = std::min(best_prev, dp[p1][p2]);
                        }
                    }
                    next_dp[c1][c2] = best_prev + c_add;
                }
            }
            dp = next_dp;
        }

        long long ans = INF;
        for (int c1 = 0; c1 < 3; ++c1) {
            for (int c2 = 0; c2 < 3; ++c2) {
                ans = std::min(ans, dp[c1][c2]);
            }
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public long minCost(int n, int[][] cost) {
        int half = n / 2;
        long INF = (long)1e18;
        long[][] dp = new long[3][3];
        for (int i = 0; i < 3; i++) Arrays.fill(dp[i], INF);

        for (int c1 = 0; c1 < 3; c1++) {
            for (int c2 = 0; c2 < 3; c2++) {
                if (c1 != c2) {
                    dp[c1][c2] = (long)cost[0][c1] + cost[n - 1][c2];
                }
            }
        }

        for (int i = 1; i < half; i++) {
            long[][] nextDp = new long[3][3];
            for (int c1 = 0; c1 < 3; c1++) Arrays.fill(nextDp[c1], INF);
            for (int c1 = 0; c1 < 3; c1++) {
                for (int c2 = 0; c2 < 3; c2++) {
                    if (c1 == c2) continue;
                    long cAdd = (long)cost[i][c1] + cost[n - 1 - i][c2];
                    long bestPrev = INF;
                    for (int p1 = 0; p1 < 3; p1++) {
                        if (p1 == c1) continue;
                        for (int p2 = 0; p2 < 3; p2++) {
                            if (p2 == c2) continue;
                            bestPrev = Math.min(bestPrev, dp[p1][p2]);
                        }
                    }
                    nextDp[c1][c2] = bestPrev + cAdd;
                }
            }
            dp = nextDp;
        }

        long ans = INF;
        for (int c1 = 0; c1 < 3; c1++) {
            for (int c2 = 0; c2 < 3; c2++) {
                ans = Math.min(ans, dp[c1][c2]);
            }
        }
        return ans;
    }
}

var minCost = function(n, cost) {
    const half = Math.floor(n / 2);
    const INF = Number.MAX_SAFE_INTEGER;
    let dp = Array.from({ length: 3 }, () => Array(3).fill(INF));

    for (let c1 = 0; c1 < 3; c1++) {
        for (let c2 = 0; c2 < 3; c2++) {
            if (c1 !== c2) {
                dp[c1][c2] = cost[0][c1] + cost[n - 1][c2];
            }
        }
    }

    for (let i = 1; i < half; i++) {
        const nextDp = Array.from({ length: 3 }, () => Array(3).fill(INF));
        for (let c1 = 0; c1 < 3; c1++) {
            for (let c2 = 0; c2 < 3; c2++) {
                if (c1 === c2) continue;
                const cAdd = cost[i][c1] + cost[n - 1 - i][c2];
                let bestPrev = INF;
                for (let p1 = 0; p1 < 3; p1++) {
                    if (p1 === c1) continue;
                    for (let p2 = 0; p2 < 3; p2++) {
                        if (p2 === c2) continue;
                        bestPrev = Math.min(bestPrev, dp[p1][p2]);
                    }
                }
                nextDp[c1][c2] = bestPrev + cAdd;
            }
        }
        dp = nextDp;
    }

    let ans = INF;
    for (let c1 = 0; c1 < 3; c1++) {
        for (let c2 = 0; c2 < 3; c2++) {
            ans = Math.min(ans, dp[c1][c2]);
        }
    }
    return ans;
};
